mapper.select:
SELECT id, title FROM question_bank WHERE id IN
#{id}
ORDER BY sort, id

SELECT id, title, description, sort, status, created_at, updated_at
FROM question_bank
WHERE id = #{id}

mapper.update:
UPDATE question_bank
SET title       = #{title},
    description = #{description},
    sort        = #{sort},
    status      = #{status}
WHERE id = #{id}

UPDATE question_bank
SET status = #{status}
WHERE id = #{id}

mapper.select:
SELECT COUNT(*)
FROM question
WHERE question_bank_id = #{bankId}

SELECT question_bank_id AS bankId, question_type AS questionType, COUNT(*) AS total, COUNT(CASE WHEN status = 1 THEN 1 END) AS enabled FROM question WHERE question_bank_id IN
#{bankId}
GROUP BY question_bank_id, question_type ORDER BY question_bank_id, question_type
